?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Facturas</title><style>body{font:15px Arial;background:#f2f7f5;color:#243b37;margin:0}.wrap{padding:22px}.box{background:white;padding:20px;border-radius:12px}h1{color:#087f73}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:10px;border-bottom:1px solid #ddd}th{background:#eaf5f1}.btn{background:#087f73;color:#fff;padding:9px 12px;border-radius:7px;text-decoration:none}</style></head><body><main class="wrap"><section class="box"><h1>Facturas</h1><p><a class="btn" href="index.php">Volver a facturación</a></p><div style="overflow:auto"><table><thead><tr><th>Número</th><th>Fecha</th><th>Cliente / ID</th><th>Pago</th><th>Total</th><th>Estado</th><th></th></tr></thead><tbody><?php while($v=$rows->fetch_assoc()){ ?><tr><td><?=htmlspecialchars($v['numero'])?></td><td><?=htmlspecialchars($v['fecha'])?></td><td><?=htmlspecialchars($v['cliente'])?> / <?=htmlspecialchars($v['id_cliente']??'')?></td><td><?=htmlspecialchars($v['metodo_pago'])?></td><td>RD$ <?=number_format((float)$v['total'],2)?></td><td><?=htmlspecialchars($v['estado'])?></td><td><a href="ver_factura.php?id=<?=(int)$v['id']?>">Ver / imprimir</a></td></tr><?php } ?></tbody></table></div></section></main></body></html>
